"The ability to sense the flow and flux of arcane energies.": "感知奥术能量流动的能力。",
"The absence of all things.": "万物的缺席。",
"The anvil or the skull, it makes no difference.": "铁砧还是头骨，并无区别。",
"The art of foretelling.": "预言的艺术。",
"The blood of gods.": "神之血。",
"The Catacrypts": "墓穴密道",
"The earth shakes at your command.": "大地听从你的号令震动。",
"The earth shakes beneath your enemies feet.": "大地在敌人脚下震动。",
"The Fetid Barrows": "恶臭坟冢",
"the gorborung": "戈尔伯隆",
"The Great Bog": "大沼泽",
"The investigation of fire.": "对火焰的探究。",
"The knowledge of what has come before reveals what is yet possible.": "了解过去揭示了未来可能之事。",
"The light fantastic.": "奇妙之光。",
"the lost menagerie": "失落动物园",
"The portal to true magic.": "通往真正魔法的大门。",
"The powers of creation and destruction, locked in your grip.": "创造与毁灭的力量尽握你手。",
"The space where a gem once was.": "曾经有一块宝石的地方。",
"The stars are an open book, to those who can read.": "星辰是一本打开的书献给那些能读懂的人。",
"The storm before the calm.": "平静前的风暴。",
"The study of air.": "对气流的研究。",
"The study of physical form.": "对物理形态的研究。",
"The study of water.": "对流水的研究。",
"The surging energy of this rune can be felt even by the least talented of mages.": "即使是最不济的法师也能感受到这符文中涌动的能量。",
"Their names reappear throughout the ages, and few believe they ever existed.": "他们的名字贯穿各个时代反复出现很少有人相信他们真实存在过。",
"There is no safe distance.": "没有安全的距离。",
"There must be a way...": "一定有什么办法……",
