"You are at your power limit.": "你已达到力量极限。",
"You can't escape the sky.": "你无法逃离天空。",
"You forged it once, call forth another.": "你曾锻造过它再次召唤一把。",
"You have no need of these dry tomes and musty old books.": "你不需要这些干巴巴的典籍和发霉的旧书。",
"You won't go down without a fight.": "你不会不战而败。",
"Your capacity for short-term exertions.": "短期爆发力的容量。",
"Your master behind you, you set off into the world alone.": "告别你的导师你独自踏上征程。",
